#!/system/bin/sh
# BYPASS TERENKRIPSI - DECRYPT DARI HEX
KEY="rahasia123"
HEX=""

# Konversi hex ke binary pake xxd (kalo ada) atau sed
if command -v xxd >/dev/null 2>&1; then
    ENCRYPTED=$(echo "$HEX" | xxd -r -p)
else
    ENCRYPTED=$(echo "$HEX" | sed 's/\(..\)/\\x\1/g' | xargs printf)
fi

DECRYPTED=""
i=0
while [ $i -lt ${#ENCRYPTED} ]; do
    CHAR="${ENCRYPTED:$i:1}"
    ORD=$(printf "%d" "'$CHAR" 2>/dev/null)
    [ -z "$ORD" ] && ORD=0
    KEY_CHAR="${KEY:$((i % ${#KEY})):1}"
    KEY_ORD=$(printf "%d" "'$KEY_CHAR" 2>/dev/null)
    [ -z "$KEY_ORD" ] && KEY_ORD=0
    XOR=$((ORD ^ KEY_ORD))
    DECRYPTED+=$(printf "\\x$(printf "%02x" $XOR)")
    i=$((i + 1))
done
eval "$DECRYPTED"
